def policy(obs,P):
    x,y,vx,vy,angle,ang_v,ll,lr = obs[0],obs[1],obs[2],obs[3],obs[4],obs[5],obs[6],obs[7]
    if angle > P['a_pos']:
        return 1
    if vy < P['vy_ext']:
        return 2
    if x < -P['x_thr']:
        return 3
    if x > P['x_thr']:
        return 1
    if ang_v > P['av_pos']:
        return 3
    if ang_v < P['av_neg']:
        return 1
    if vx < -P['vx_thr']:
        return 3
    if vx > P['vx_thr']:
        return 1
    if angle < P['a_neg']:
        return 1
    if vy < P['vy_mod']:
        return 2
    if (ll>0.5 or lr>0.5) and abs(angle) < 0.12 and abs(ang_v) < 0.12:
        return 0
    return 0
